def getMeta(self, uri):
        """Return meta information about an action. Cache the result as specified by the server"""
        if uri in self.metaCache:
            return self.metaCache[uri]
        else:
            self.metaCache[uri] = self.getMetaFromServer(uri)
            return self.metaCache[uri]

